    [300+Math.cos(t*0.42+7)*105,30+Math.sin(t*0.52+3)*45,0.095,1.6,-0.7]
  ];
  let aS=0,iS=0,cS=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph*0.5);
    cS+=Math.cos(d*f*0.5-t*sp*0.4+ph*2);
  }
  const n=src.length,act=aS/n,inh=iS/n,cross=cS/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.07+sy*0.01-t*0.6)+Math.sin(-sx*0.02+sy*0.06+t*1.4))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin((sx*0.5+sy)*0.08+t*1.8)*0.15;
