  const r1=act-inh*0.7+bg*0.3+spiral,r2=cross*0.5+act*inh*0.3+frac;
  const reaction=Math.tanh((r1+r2*0.4)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3)*1.5)*0.3;
  const blend=reaction*0.65+cell*0.2+cross*0.15,v=blend*0.5+0.5;
  const pal=[[5,12,52],[10,45,85],[15,85,110],[20,140,125],[60,175,120],[160,195,80],[220,190,60],[235,145,55],[220,95,65],[185,55,75],[120,35,80],[65,22,68],[30,15,58],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sf=(1-Math.cos(f*Math.PI))/2;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge=Math.abs(reaction)>0.7?1.15:Math.abs(reaction)>0.4?1.05:1.0;
  const shimmer=0.95+Math.sin(t*3+dist*0.1)*0.05;
  const fl=lum*edge*shimmer;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*fl)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*fl)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*fl)|0
  ];
}
